function highlightRegion(k){const all=!k||k==='GLOBAL';d3.selectAll('#regionMap .rm-country').classed('dim',function(){return !all&&this.dataset.region!==k}).classed('hot',function(){return !!k&&!all&&this.dataset.region===k});document.querySelectorAll('#smallMultiples .mini').forEach(m=>m.classList.toggle('linked',m.dataset.region===k));document.querySelectorAll('#vaccineBars rect,#incidenceBars rect').forEach(b=>b.classList.toggle('bar-faded',!all&&b.dataset.region!==k));$('#regionMapNote').textContent=k?(k==='GLOBAL'?'Global · all countries':`${k} · ${REGIONS[k]}`):'Hover a region or a chart to link them'}
function renderRegions(){updateFilterSummary();if(state.regionMapData!==state.data)initRegionMap();const all=filtered(true),start=+$('#startYear').value,end=+$('#endYear').value;const groups=['GLOBAL',...Object.keys(REGIONS)].filter(k=>!state.regions.size||state.regions.has(k));$('#smallMultiples').replaceChildren();groups.forEach(k=>{const rr=all.filter(r=>(k==='GLOBAL'||r.region===k)&&r.year>=start&&r.year<=end),a=yearly(rr).map(o=>withOfficial(o,k,o.year));const box=document.createElement('div');box.className='mini';box.dataset.region=k;box.tabIndex=0;box.style.setProperty('--region',REGION_COLORS[k]);box.onpointerenter=box.onfocus=()=>highlightRegion(k);box.onpointerleave=box.onblur=()=>highlightRegion(null);const h=document.createElement('h3');h.textContent=k==='GLOBAL'?'Global':k;const p=document.createElement('p');p.textContent=k==='GLOBAL'?'All countries in the current selection':REGIONS[k];box.append(h,p);$('#smallMultiples').append(box);lineChart(box,completeYears(a,start,end),['mcv1','incidence'],{width:390,height:205,mini:true,coverage:true,dual:true,domain:[start,end]})});const picked=Object.keys(REGIONS).filter(k=>state.regions.has(k)),regions=Object.keys(REGIONS).filter(k=>!picked.length||picked.includes(k)).map(region=>withOfficial({region,...aggregate(all.filter(r=>r.region===region&&r.year===currentYear()))},region,currentYear()));$('#vaccineBarsNote').textContent=`MCV1 / MCV2 · % · ${currentYear()}`;$('#incidenceBarsNote').textContent=`Per 100,000 population · ${currentYear()}`;bars('#vaccineBars',regions,['mcv1','mcv2'],100,'Coverage (%)');bars('#incidenceBars',regions.map(r=>({...r,incidence:available(r.incidence)?r.incidence/10:null})),['incidence'],null,'Cases per 100,000');}
function bars(target,rows,keys,max,yLabel){$(target).replaceChildren();const svg=d3.select(target).append('svg').attr('class','chart-svg').attr('viewBox','0 0 560 270').attr('role','img').attr('aria-label','Regional bar comparison'),x=d3.scaleBand().domain(rows.map(r=>r.region)).range([55,535]).padding(.35),y=d3.scaleLinear().domain([0,max||d3.max(rows,r=>r.incidence)||1]).nice().range([225,30]);svg.append('g').attr('class','axis').attr('transform','translate(55,0)').call(d3.axisLeft(y).ticks(4).tickSize(-480));if(yLabel)svg.append('text').attr('class','axis-label').attr('transform','translate(13,127) rotate(-90)').attr('text-anchor','middle').text(yLabel);svg.append('g').attr('class','axis').attr('transform','translate(0,225)').call(d3.axisBottom(x).tickSize(0).tickPadding(15));rows.forEach(r=>keys.forEach((k,i)=>{if(!available(r[k])){svg.append('text').attr('x',x(r.region)+x.bandwidth()/2).attr('y',215-i*14).attr('text-anchor','middle').attr('font-size',8).attr('fill','#84988c').text('No data');return}const bw=x.bandwidth()/keys.length;svg.append('rect').attr('data-region',r.region).attr('x',x(r.region)+i*bw).attr('width',bw-3).attr('y',y(r[k])).attr('height',225-y(r[k])).attr('rx',3).attr('fill',k==='incidence'?'#d58b51':i?'#a7cdbd':'#147d70').append('title').text(`${r.region} · ${k}: ${fmt(r[k],2)}`)}))}
function stop(){clearInterval(state.timer);state.timer=null;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play years')}
function loadData(data,label){stop();state.data=data;state.useOfficial=!label;state.selectedYears=null;state.hasCases=data.some(r=>available(r.cases));const caseOpt=$('#metric').querySelector('[value="cases"]');caseOpt.hidden=caseOpt.disabled=!state.hasCases;if(!state.hasCases&&$('#metric').value==='cases')$('#metric').value='incidence';const years=[...new Set(data.map(r=>r.year))].sort((a,b)=>a-b);$('#year').min=years[0];$('#year').max=years.at(-1);$('#year').value=years.at(-1);$('#yearEnd').textContent=years.at(-1);['startYear','endYear'].forEach(k=>{$('#'+k).min=years[0];$('#'+k).max=years.at(-1)});$('#startYear').value=years[0];$('#endYear').value=years.at(-1);updateRange();const countries=[...new Map(data.map(r=>[r.iso3,r.country])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));$('#country').replaceChildren(...countries.map(([iso,name])=>new Option(name,iso)));$('#country').value=countries.some(([iso])=>iso==='IND')?'IND':countries[0][0];$('#datasetName').textContent=label||'WHO measles data';$('#datasetDetail').replaceChildren(...(label?[`${data.length.toLocaleString()} rows loaded`,'processed locally in your browser']:['WHO reported incidence and WHO/UNICEF (WUENIC) coverage',`${new Set(data.map(r=>r.iso3)).size} countries, ${years[0]}–${years.at(-1)}`]).flatMap((t,i)=>{const sep=document.createElement('span');sep.className='sep';sep.setAttribute('aria-hidden','true');sep.textContent='|';return i?[sep,t]:[t]}));clearFilters(false);render()}
function clearFilters(draw=true){$('#gavi').checked=false;document.querySelectorAll('[name="development"],[name="income"],[name="development-all"],[name="income-all"]').forEach(n=>{n.checked=true;n.indeterminate=false});state.regions.clear();updateChips();if(draw)render()}
function parseCSV(text){const parsed=d3.csvParse(text.replace(/^\uFEFF/,''));const cols=parsed.columns;if(!['country','iso3','year'].every(k=>cols.includes(k)))throw Error('Required columns: country, iso3, year. See the README for the full schema.');if(!['incidence','cases','mcv1','mcv2'].some(k=>cols.includes(k)))throw Error('Include at least one measure: incidence, cases, mcv1, or mcv2.');const seen=new Set();const rows=parsed.map((r,i)=>{const row={...r,country:r.country.trim(),iso3:r.iso3.trim().toUpperCase()};if(!row.country||!(/^[A-Z]{3}$/.test(row.iso3)))throw Error(`Row ${i+2}: country and a three-letter ISO3 code are required.`);for(const k of ['year','population','cases','incidence','mcv1','mcv2']){const v=(r[k]||'').trim();row[k]=v===''?null:Number(v);if(v!==''&&!Number.isFinite(row[k]))throw Error(`Row ${i+2}: ${k} must be numeric or blank.`)}if(!Number.isInteger(row.year)||row.year<1900||row.year>2100)throw Error(`Row ${i+2}: year must be a whole number from 1900 to 2100.`);for(const k of ['population','cases','incidence','mcv1','mcv2'])if(row[k]!=null&&(row[k]<0||(k.startsWith('mcv')&&row[k]>100)||(k==='population'&&row[k]===0)))throw Error(`Row ${i+2}: invalid ${k}; coverage must be 0–100 and population positive.`);const key=row.iso3+row.year;if(seen.has(key))throw Error(`Row ${i+2}: duplicate country/year ${key}.`);seen.add(key);const flag=(r.gavi_eligible||'').trim().toLowerCase();if(!['','true','false','1','0','yes','no'].includes(flag))throw Error(`Row ${i+2}: gavi_eligible must be true or false.`);row.gavi_eligible=['true','1','yes'].includes(flag);for(const k of ['region','income_group','development_status'])row[k]=(r[k]||'').trim();if(row.region&&!Object.hasOwn(REGIONS,row.region))throw Error(`Row ${i+2}: use a WHO region code (AFRO, AMRO, EMRO, EURO, SEARO, WPRO).`);if(row.incidence===null&&row.cases!==null&&row.population)row.incidence=row.cases/row.population*1e6;return row});if(!rows.length)throw Error('The dataset contains no data rows.');if(!rows.some(r=>['incidence','cases','mcv1','mcv2'].some(k=>available(r[k]))))throw Error('No numeric observations found.');return rows}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#compareToggle').onchange=e=>{state.compare=e.target.checked;$('#map2Panel').hidden=!state.compare;$('.map-layout').classList.toggle('compare',state.compare);$('#metricWrap').hidden=state.compare;render()};document.querySelectorAll('[data-dose]').forEach(b=>b.onclick=()=>{state.dose=b.dataset.dose;document.querySelectorAll('[data-dose]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b)});render()});$('#clearFiltersRegions').onclick=()=>clearFilters();['metric','gavi','country'].forEach(k=>$('#'+k).onchange=()=>{state.selectedYears=null;render()});$('#year').oninput=render;$('#clearFilters').onclick=()=>clearFilters();$('#play').onclick=()=>{if(state.timer){stop();return}$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause years');if(+$('#year').value===+$('#year').max)$('#year').value=$('#year').min;render();state.timer=setInterval(()=>{if(+$('#year').value>=+$('#year').max){stop();return}$('#year').value=+$('#year').value+1;render()},700)};['startYear','endYear'].forEach(k=>$('#'+k).oninput=()=>{const s=$('#startYear'),e=$('#endYear');if(+s.value>+e.value)$('#'+k).value=k==='startYear'?e.value:s.value;updateRange();render()});$('#methodology').onclick=()=>$('#dataDialog').showModal();$('#closeDialog').onclick=()=>$('#dataDialog').close();
(async()=>{try{const [world,demo,officialText]=await Promise.all([fetch('assets/world.geojson').then(r=>{if(!r.ok)throw Error('Map could not load');return r.json()}),fetch('who_measles.csv').then(r=>r.text()),fetch('who_measles_official.csv').then(r=>r.ok?r.text():'').catch(()=>'')]);state.world=world;state.demo=parseCSV(demo);state.official=new Map(officialText?d3.csvParse(officialText).filter(r=>r.incidence!=='').map(r=>[r.region+'|'+r.year,+r.incidence]):[]);[[INCOME,'income'],[DEV,'development']].forEach(([list,name])=>{const box=(label,inputName,onchange)=>{const l=document.createElement('label');l.className='check';const i=document.createElement('input');i.type='checkbox';i.name=inputName;i.value=label;i.onchange=()=>{onchange(i);state.selectedYears=null;render()};l.append(i,document.createTextNode(label));$('#'+name+'Filters').append(l);return l};box('All',name+'-all',i=>document.querySelectorAll(`[name="${name}"]`).forEach(n=>n.checked=i.checked)).classList.add('check-all');list.forEach(d=>box(d,name,()=>syncAll(name)))});initRegionChips();initMap();loadData(state.demo)}catch(e){toast(`Unable to start: ${e.message}. Run the app with the Python server.`)}})();
